// Calls the model through the Bifrost gateway with a virtual key.
const res = await fetch('http://localhost:8080/v1/chat/completions', {
  method: 'POST',
  headers: { 'content-type': 'application/json', 'x-bf-vk': process.env.BIFROST_VK ?? '' },
  body: JSON.stringify({ model: 'openai/gpt-4o', messages: [{ role: 'user', content: 'Summarise this file' }] }),
});
console.log((await res.json()).choices[0].message.content);
